// ============ 门店评分派生 ============

/**
 * 计算门店评分：最近30天平均，若无记录则取最近一次
 * 口径统一，门店详情、列表、Dashboard 排行都调用此函数
 * 返回 null 表示无巡检记录（新门店）
 */
export function calculateStoreScore(
  storeId: string,
  inspections: Inspection[]
): number | null {
  const storeInspections = inspections
    .filter((i) => i.storeId === storeId)
    .sort((a, b) => b.inspectTime.localeCompare(a.inspectTime));

  if (storeInspections.length === 0) return null;

  // 最近30天的巡检
  const now = new Date();
  const thirtyDaysAgo = new Date(now.getTime() - 30 * 24 * 60 * 60 * 1000);
  const recent30 = storeInspections.filter((i) => {
    const d = new Date(i.inspectTime.replace(/-/g, "/"));
    return d >= thirtyDaysAgo;
  });

  // 有近30天记录则取平均，否则取最近一次
  if (recent30.length > 0) {
    return Math.round(recent30.reduce((s, i) => s + i.score, 0) / recent30.length);
  }
  return storeInspections[0].score;
}

// ============ 门店数据 ============

// 获取所有门店（新建在前，mock在后）
export function useAllStores(): Store[] {
  const extraStores = useStore((s) => s.extraStores);
  return [...extraStores, ...stores];
}

// 获取单个门店（按 ID）
export function useStoreById(id: string): Store | undefined {
  const extraStores = useStore((s) => s.extraStores);
  const all = [...extraStores, ...stores];
  return all.find((s) => s.id === id);
}

// 统一门店名称查询：合并 mock + 用户新建门店
export function useStoreName(id: string): string {
  const extraStores = useStore((s) => s.extraStores);
  const all = [...extraStores, ...stores];
  const found = all.find((s) => s.id === id);
  return found ? found.name : "未知门店";
}

// 门店评分 hook：从巡检记录派生，新门店返回 null
export function useStoreScore(storeId: string): number | null {
  const extraInspections = useStore((s) => s.extraInspections);
  const allInspections = [...extraInspections, ...mockInspections];
  return calculateStoreScore(storeId, allInspections);
}

// ============ 巡检数据 ============

// 获取所有巡检（新建在前，mock在后）
export function useAllInspections(): Inspection[] {
  const extraInspections = useStore((s) => s.extraInspections);
  return [...extraInspections, ...mockInspections];
}

// 获取单条巡检 —— 找不到返回 undefined，由页面处理"记录不存在"
export function useInspection(id: string): Inspection | undefined {
  const extraInspections = useStore((s) => s.extraInspections);
  const all = [...extraInspections, ...mockInspections];
  return all.find((i) => i.id === id);
}

// 按门店获取巡检
export function useInspectionsByStore(storeId: string): Inspection[] {
  const extraInspections = useStore((s) => s.extraInspections);
  const all = [...extraInspections, ...mockInspections];
  return all.filter((i) => i.storeId === storeId);
}

// ============ 照片数据 ============

// 获取巡检的照片（合并 mock photos + 用户新建的 evidences）
// Evidence 包含 Photo 的所有展示字段，可统一作为 Photo 使用
export function usePhotosByInspection(inspectionId: string): Photo[] {
  const extraEvidences = useStore((s) => s.extraEvidences);
  // Evidence 结构兼容 Photo，直接合并
  const allPhotos: Photo[] = [...extraEvidences, ...mockPhotos];
  return allPhotos.filter((p) => p.inspectionId === inspectionId);
}

// 获取单张照片（含 evidence）
export function usePhoto(photoId: string): Photo | undefined {
  const extraEvidences = useStore((s) => s.extraEvidences);
  const allPhotos: Photo[] = [...extraEvidences, ...mockPhotos];
  return allPhotos.find((p) => p.id === photoId);
}

// 获取巡检的取证实体（仅用户新建巡检有 evidence）
export function useEvidencesByInspection(inspectionId: string): Evidence[] {
  const extraEvidences = useStore((s) => s.extraEvidences);
  return extraEvidences.filter((e) => e.inspectionId === inspectionId);
}

// ============ 风险数据 ============

// 获取所有风险（从 store 读取，包含状态变更）
export function useAllRisks(): Risk[] {
  return useStore((s) => s.risks);
}

// 获取巡检的风险
export function useRisksByInspection(inspectionId: string): Risk[] {
  const risks = useStore((s) => s.risks);
  return risks.filter((r) => r.inspectionId === inspectionId);
}

// ============ 整改闭环数据 ============

// 获取风险的整改任务
export function useRectificationTask(riskId: string): RectificationTask | undefined {
  const tasks = useStore((s) => s.rectificationTasks);
  return tasks.find((t) => t.riskId === riskId);
}

// 获取风险的审计事件（按时间正序）
export function useAuditEvents(riskId: string): AuditEvent[] {
  const events = useStore((s) => s.auditEvents);
  return events
    .filter((e) => e.riskId === riskId)
    .sort((a, b) => a.timestamp.localeCompare(b.timestamp));
}

// ============ Dashboard 统计 ============

export function useDashboardStats() {
  const risks = useStore((s) => s.risks);
  const extraInspections = useStore((s) => s.extraInspections);
  const allInspections = [...extraInspections, ...mockInspections];

  // 待整改风险：包含待确认 + 已确认待整改 + 整改中（未闭环的都算待整改）
  const pendingCount = risks.filter(
    (r) =>
      r.status === "pending" ||
      r.status === "ai_detected" ||
      r.status === "confirmed" ||
      r.status === "fixing"
  ).length;

  // 整改完成率：已验证 / 全部风险
  const verifiedCount = risks.filter((r) => r.status === "verified").length;
  const fixRate =
    risks.length > 0 ? Math.round((verifiedCount / risks.length) * 100) : 0;

  // 高风险门店：有未闭环高风险项的门店（已验证的不算）
  const highRiskStoreIds = new Set(
    risks
      .filter((r) => r.level === "high" && r.status !== "verified")
      .map((r) => {
        const insp = allInspections.find((i) => i.id === r.inspectionId);
        return insp?.storeId;
      })
      .filter(Boolean)
  );

  // 本月巡检次数：本月有数据则用本月，无数据返回 0（不回退到总数）
  const now = new Date();
  const thisMonth = allInspections.filter((i) => {
    const d = new Date(i.inspectTime);
    return (
      d.getMonth() === now.getMonth() && d.getFullYear() === now.getFullYear()
    );
  }).length;

  return {
    monthlyInspections: thisMonth,
    pendingRisks: pendingCount,
    fixRate,
    highRiskStores: highRiskStoreIds.size,
    totalRisks: risks.length,
    totalInspections: allInspections.length,
  };
}

// 门店排行（含新建门店，评分从巡检记录派生）
// 返回 store + 派生 score，避免页面再次读取静态 avgScore
export function useStoreRankings(): { top5: { store: Store; score: number }[]; bottom5: { store: Store; score: number }[] } {
  const extraStores = useStore((s) => s.extraStores);
  const extraInspections = useStore((s) => s.extraInspections);
  const all = [...extraStores, ...stores];
  const allInspections = [...extraInspections, ...mockInspections];

  // 为每个门店计算派生评分，无巡检记录的门店不参与排行
  const scored = all
    .map((store) => ({
      store,
      score: calculateStoreScore(store.id, allInspections),
    }))
    .filter((x): x is { store: Store; score: number } => x.score !== null);

  const sorted = scored.sort((a, b) => b.score - a.score);
  return {
    top5: sorted.slice(0, 5),
    bottom5: sorted.slice(-5).reverse(),
  };
}

